<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();$c=obtener_caso((int)$_GET['id']);$fase=(int)$_GET['fase'];if($_SERVER['REQUEST_METHOD']==='POST'){try{validar_token();$nota=trim($_POST['nota']??'');if($fase===2){$tipo=$_POST['tipo_caso'];$s=bd()->prepare("UPDATE casos_actualizacion SET tipo_caso=?,analisis_clasificacion=?,estado='CLASIFICADO',fase_actual=2 WHERE id_caso=?");$s->bind_param('ssi',$tipo,$nota,$c['id_caso']);}elseif($fase===3){$s=bd()->prepare("UPDATE casos_actualizacion SET planeacion=?,estado='PLANEACION_COMPLETA',fase_actual=3 WHERE id_caso=?");$s->bind_param('si',$nota,$c['id_caso']);}elseif($fase===4){$req=isset($_POST['requiere_encuesta'])?1:0;$ap=(int)$_POST['encuestas_aplicadas'];$fav=(int)$_POST['respuestas_favor'];$con=(int)$_POST['respuestas_contra'];$s=bd()->prepare("UPDATE casos_actualizacion SET trabajo_campo=?,requiere_encuesta=?,modelo_encuesta=?,encuestas_aplicadas=?,respuestas_favor=?,respuestas_contra=?,estado='CAMPO_COMPLETO',fase_actual=4 WHERE id_caso=?");$s->bind_param('sisiiii',$nota,$req,$_POST['modelo_encuesta'],$ap,$fav,$con,$c['id_caso']);}elseif($fase===5){if(!requiere_actualizacion_externa($c['tipo_caso']))throw new RuntimeException('La fase no aplica al tipo de caso.');$s=bd()->prepare("UPDATE casos_actualizacion SET actualizacion_externa=?,estado='ACTUALIZACION_EXTERNA_COMPLETA',fase_actual=5 WHERE id_caso=?");$s->bind_param('si',$nota,$c['id_caso']);}elseif($fase===6){$s=bd()->prepare("UPDATE casos_actualizacion SET propuesta_distrital=?,estado='PROPUESTA_COMPLETA',fase_actual=6 WHERE id_caso=?");$s->bind_param('si',$nota,$c['id_caso']);}elseif($fase===7){if(!es_control())throw new RuntimeException('Solo control general puede revisar.');$s=bd()->prepare("UPDATE casos_actualizacion SET revision_tecnica=?,resultado_tecnico=?,estado='EN_REVISION',fase_actual=7 WHERE id_caso=?");$s->bind_param('ssi',$nota,$_POST['resultado_tecnico'],$c['id_caso']);}elseif($fase===8){$s=bd()->prepare("UPDATE casos_actualizacion SET cierre_expediente=?,estado='CERRADO',fase_actual=8,fecha_cierre=NOW() WHERE id_caso=?");$s->bind_param('si',$nota,$c['id_caso']);}else throw new RuntimeException('Fase inválida.');$s->execute();bitacora('FASE_COMPLETADA',$c['id_caso'],'Fase '.$fase);mensaje('Fase guardada correctamente.');ir('caso.php?id='.$c['id_caso']);}catch(Throwable $e){mensaje($e->getMessage(),'error');ir('caso.php?id='.$c['id_caso']);}}$nombres=['','Registro','Clasificación','Planeación','Campo y encuestas','Actualización externa','Propuesta','Revisión técnica','Cierre'];include 'encabezado.php';?><section class="tarjeta"><h1>Fase <?=$fase?>. <?=h($nombres[$fase]??'')?></h1><form method="post"><input type="hidden" name="token" value="<?=token()?>"><?php if($fase===2):?><label>Tipo de caso</label><select name="tipo_caso" required><option value="DIVISION">División</option><option value="FUSION">Fusión</option><option value="CAMBIO_NOMENCLATURA">Cambio de nomenclatura</option><option value="INCLUSION_EXCLUSION_SECCIONES">Inclusión/exclusión de secciones electorales</option><option value="INCLUSION_EXCLUSION_MANZANAS">Inclusión/exclusión de manzanas electorales</option><option value="COMBINACION">Combinación</option><option value="OTRO">Otro</option></select><?php elseif($fase===4):?><label><input style="width:auto" type="checkbox" name="requiere_encuesta"> Requiere encuesta</label><label>Modelo</label><select name="modelo_encuesta"><option>No aplica</option><option>MGPC-C1 Ciudadanía</option><option>MGPC-C2 COPACO</option></select><div class="rejilla-3"><div><label>Aplicadas</label><input type="number" min="0" name="encuestas_aplicadas" value="0"></div><div><label>A favor</label><input type="number" min="0" name="respuestas_favor" value="0"></div><div><label>En contra</label><input type="number" min="0" name="respuestas_contra" value="0"></div></div><?php elseif($fase===7):?><label>Resultado técnico</label><select name="resultado_tecnico"><option>Viable</option><option>Viable con ajustes</option><option>Inviable</option><option>Pendiente de información externa</option><option>Reservado para actualización posterior</option></select><?php endif?><label>Descripción, actividades, fundamento y observaciones</label><textarea name="nota" rows="11" required></textarea><button class="boton">Guardar y continuar</button></form></section><?php include 'pie.php';?>